#!/bin/bash
# UDPserver Manager - Protected Build
# (c) chanelog - All Rights Reserved
_K="udpserver_chanelog_2026"
_D=''
_run(){
  local _t
  _t=$(mktemp /tmp/.udp_XXXXXX 2>/dev/null) || exit 1
  trap 'rm -f "$_t" 2>/dev/null' EXIT INT TERM
  printf '%s' "$_D" | openssl enc -aes-256-cbc -pbkdf2 -iter 100000 -d -pass pass:"$_K" -base64 -A 2>/dev/null | gunzip -c > "$_t" 2>/dev/null
  if [[ ! -s "$_t" ]]; then
    echo "Error: Gagal memuat script. File mungkin rusak." >&2
    exit 1
  fi
  chmod 700 "$_t"
  bash "$_t" "$@"
}
_run "$@"
